import json,hashlib,copy
from pathlib import Path
P=Path(__file__).parent; R=P.parents[3]
old=R/'docs/research/engine-pass3/head-valve-inspect-reseal-bench-v1.procedure.json'
d=json.loads(old.read_text()); originals={s['id']:s for s in d['steps']};steps=[]
URL=d['source']['source_url']
def add(i,t,a,p,v,record=True,diagram=True):
 steps.append(dict(id=i,title=t,instruction=a,source_pdf_pages=p,verification=[v],record_required=record,diagram_reference_required=diagram,source_links=[URL+'#page='+str(x) for x in p] if diagram else [],depends_on=[steps[-1]['id']] if steps else [],origin='Original OEM summary; specialist work-order and recorded acceptance are explicit workflow adaptations.'))
def inherit(i):
 s=copy.deepcopy(originals[i]);s['instruction']=s['instruction'].replace('on this reuse route','during inspection');s['depends_on']=[steps[-1]['id']] if steps else [];steps.append(s)
add('entry','Confirm the head repair and machining plan','Start with the original cylinder head removed and cams out. This bench route renews all four guides and valves while retaining an undamaged original head and serviceable lifters. Arrange specialist valve-seat refacing before starting; this guide records its required result and does not teach seat cutting. Keep the two intake and two exhaust positions identified. Obtain four new guides, four sacrificial new titanium lapping valves, four separate new running valves and four new stem seals, all matched to the exact stock head.',[229,230,231,232,233],'Record exact head identity, parts and arranged seat-refacing service.')
for i in ['lifters','sealing','strip','guide-check','valve-check','seat-check','spring-check']:inherit(i)
add('eligibility','Confirm this head can be retained','Continue only with undamaged original head, serviceable lifters and seats without source-directed replacement faults. Seat pitting/wear or contact width beyond 1.5 mm requires head replacement; scratched or damaged lifters require lifters and head replacement. Those replacement-head branches are outside this route. Record each spring disposition; replace any spring below its stated limit.',[231,232,233],'Original head, seat and lifter eligibility recorded; spring replacements identified.')
add('heat','Heat the stripped head','Remove solvent and prepare the stripped head for oven heating. Heat the head to 100 °C as specified to assist guide removal and installation and maintain correct fit. Use suitable heat protection and stable support.',[230],'Record head heating to 100 °C; head securely supported.')
add('guides-out','Remove the old guides','Use the 5.5 mm valve-guide remover from set 90890-04016, or YM-01122 with the proper installer equipment, in the direction illustrated. Remove each old guide without damaging its bore in the head.',[230,231],'Four guides removed; head bores undamaged.',False)
add('guides-in','Install the new guides','Use the illustrated guide installer and remover to install each new guide in the heated head. Measure installed height from the exact illustrated head surface: intake 13.5–13.9 mm and exhaust 12.2–12.6 mm. Keep intake and exhaust positions distinct.',[230,231],'Record all four guide projections and accepted seating.')
add('ream','Finish the installed guide bores','Use 5.5 mm reamer 90890-01196 or YM-01196 after installation to obtain the proper valve-to-guide fit. Measure each finished guide bore and its matching new running-valve stem. Both intake and exhaust guide ID specification is 5.500–5.512 mm. Calculate ID minus stem OD; clearance limits are intake 0.080 mm and exhaust 0.100 mm. Reject a new running valve whose stem OD is below the intake 5.445 mm or exhaust 5.435 mm limit, even if calculated clearance passes. Measure new-valve stem runout against 0.020 mm. Record actual dimensions and reject an out-of-specification fit; the wear limits are not machining targets.',[50,230,231],'Record four bore IDs, stem ODs, clearances and runouts; all dimensions accepted.')
add('seat-service','Have the seats refaced after guide renewal','Send the guide-finished head to the arranged head-machining specialist for the valve-seat refacing required after guide renewal. Supply the exact head identity, guide and valve measurements and the source diagrams. Record the returned head and completed work before proceeding. This is an outsourced machining stage: no cutter angle, cut depth or removal allowance is supplied by this guide.',[230,231,232],'Record specialist, work order and completed refacing; inspect returned head for damage.')
add('lap-coarse','Lap with the sacrificial new valves','Use only the separately identified NEW sacrificial valves for lapping. Put coarse compound on the valve face, keeping compound out of the stem-to-guide gap. Lubricate the stem with molybdenum-disulfide oil, insert it and turn/tap with the valve lapper until face and seat are uniformly polished as described and shown. Do not reuse an original running titanium valve for this operation.',[232],'Sacrificial valves identified; coarse contact uniform.',False)
add('lap-fine','Clean and finish the lapped contact','Remove all coarse compound. Repeat the lapping process with fine compound, then clean off all compound again. Clean the face and seat whenever changing or completing a lapping stage. Do not leave abrasive material in the head or guide.',[232],'Coarse and fine compound completely removed.',False)
add('contact','Measure the finished seat contact','Apply blue layout fluid to the valve face, press it through the guide onto the seat and measure the clean contact impression. Record all four contact widths against the 1.5 mm intake/exhaust limit and inspect for uniform contact. If outside specification, return to the specialist refacing and lapping operation before proceeding; do not assemble a failed seat.',[231,232],'Record all four accepted widths and contact patterns.')
add('running-valves','Set aside every lapping valve','Permanently separate the four sacrificial lapping valves from the running parts. Install only the four DIFFERENT new running valves whose identities and fit were recorded. A titanium valve used for lapping must never run in the engine. Clean all parts and confirm no lapping compound remains.',[231,232],'Record distinct running-valve identities; all sacrificial valves excluded from assembly.')
add('assemble','Install the new seals and running valves','Clean stem ends. Lubricate new running-valve stems and new stem seals with molybdenum-disulfide oil. Install spring seat, new seal, matching new running valve, accepted spring and retainer in each recorded position. Fit the larger-pitch spring coils upward.',[233],'Four new running valves and seals fitted; springs correctly oriented.',False)
inherit('cotters')
add('seal-final','Verify the assembled valves seal','Repeat the port solvent sealing check with the new running valves now retained by their springs. Record each intake and exhaust result; any leakage requires resolution before this head leaves the bench. Remove all test solvent afterward.',[229],'Four running-valve sealing results accepted; solvent removed.')
inherit('lifters-install')
d.update(id='yamaha-2026-yz450f-guides-valves-renew-bench-v1',title='Renew valve guides and valves with seat machining',publication_status='APPROVED',steps=steps,completeness='Complete declared bench renewal workflow with an explicit outsourced seat-refacing stage; not an in-app seat-cutting procedure or assembled-bike top-end route.',entry_state=['Original head removed, cams out; head and lifters serviceable.','Exact new guides, separate sacrificial and running valves, seals and arranged specialist refacing available.'],exit_state=['Renewed guides and separate new running valves accepted and assembled; original serviceable lifters/pads restored.','Head remains on bench; cam timing, clearance adjustment, installation and engine commissioning still required.'])
d['source'].update(pdf_pages=sorted(set(p for s in steps for p in s['source_pdf_pages'])),printed_pages=['2-3','5-24','5-25','5-26','5-27','5-28','5-29','5-30','5-31'],review_status='APPROVED',review_note='Exact PDF50 and230–234 visually reviewed in pass7; inherited bench strip229 previously approved. Specialist-refacing stage explicit, no cutter settings inferred. Independent year_groups_research visual review230–234 approved after explicit stem-OD rejection and dependency-hash verification corrections.')
d['applicability']['excluded']=['Whole-head or lifter replacement','Valve-seat cutter selection/angles/depth or welding','Other years/models/markets','Whole-bike access and engine commissioning']
d['preflight']=['Original head removed and cams out; exact four positions identified.','Original head/lifters serviceable; new guide/valve parts and specialist refacing arranged.']
d.pop('material_policy',None)
d['required_parts']=[dict(name=x) for x in ['Four exact stock new guides','Four sacrificial new titanium lapping valves','Four separate new titanium running valves','Four new stem seals','Exact stock springs where inspection requires']]
d['required_tools'] += [dict(name=x) for x in ['Controlled oven and means to confirm 100 °C; hot-work protection/support','5.5 mm guide removal/installer set 90890-04016 (YM-01122 is remover only)','5.5 mm reamer 90890-01196 / YM-01196','Guide projection measuring tool','Arranged specialist seat-refacing equipment/service']]
d['consumables']=['Molybdenum-disulfide oil','Engine oil','Coarse and fine valve-lapping compound','Blue layout fluid','Clean test solvent']
d['prerequisites']=['Head removal and cams-out access completed under the separate approved operation.','No head/lifter replacement fault; specialist seat-refacing service arranged before guide work.']
d['critical_stop_conditions']=['Head, seat or lifter damage requiring head replacement','Unacceptable guide fit, projection, runout, contact or sealing','Lapping valve mixed with new running valves or abrasive contamination']
d['operation_dependencies']=[dict(artifact='docs/research/engine-pass3/head-valve-inspect-reseal-bench-v1.procedure.json',sha256=hashlib.sha256(old.read_bytes()).hexdigest(),purpose='Inherited source-reviewed bench stripping and retained lifter/cotter methods; new guide/valve branch supersedes reuse-only eligibility in this candidate.')]
d['external_operations']=[dict(id='seat-refacing',step='seat-service',type='OUTSOURCED_MACHINING',reason='OEM requires refacing after guide replacement; exact operation pages supply no cutter geometry/depth.',source_pdf_pages=[230,231,232])]
(P/'guides-valves-renew-bench-v1.procedure.json').write_text(json.dumps(d,indent=2)+'\n',encoding='utf-8');print(len(steps))
